p='src/server/jobs/cleanup-archived-job.ts'
s=open(p).read()
head_end=s.index("const ORG_BATCH")
new_head='''/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, isArchived
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { IsoTimestamp, IssueId, OrgId } from "@/types/common";
import type { Issue } from "@/types/issue";

const PAGE_SIZE = 100;
const MS_PER_DAY = 24 * 60 * 60 * 1000;
const BYTES_PER_MB = 1024 * 1024;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. An archived issue is a trash entry that stays
 * restorable for as long as the plan promises: the cut-off comes from
 * `retentionDays`, so an enterprise tenant keeps years of history where a free
 * one keeps a month. Once an issue is past it, the sweep deletes it for good —
 * the row, its label links, comments and attachments, their search documents,
 * and the storage the attachments were counted for. The audit rows past the
 * window are purged outright as well.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await orgRepo.listOrgIds();

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = toIsoTimestamp(
        new Date(now.getTime() - retentionDays * MS_PER_DAY),
      );

      await purgeExpiredIssues(orgId, cutoff, result);

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Walks every expired issue of the workspace, page by page in id order. One
 * issue failing is counted and skipped; it never stops the rest of the sweep.
 */
async function purgeExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
  result: JobResult,
): Promise<void> {
  let afterId: IssueId | null = null;

  for (;;) {
    const page = await issueRepo.listExpiredIssues(
      orgId,
      cutoff,
      afterId,
      PAGE_SIZE,
    );
    if (page.length === 0) return;

    for (const issue of page) {
      afterId = issue.id;
      if (!isArchived(issue)) continue;

      try {
        if (await purgeIssue(orgId, issue)) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("issue purge failed", {
          orgId,
          issueId: issue.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  }
}

/**
 * Deletes one expired issue and everything that hangs off it. The search
 * documents go first, while the comment ids can still be read; the rows follow
 * in one transaction; the attachments' megabytes are given back last, using the
 * sizes that transaction actually deleted. `issues_used` is left alone —
 * archived issues were never counted in it.
 *
 * Returns false when there was nothing left to purge (restored or removed
 * since it was listed).
 */
async function purgeIssue(orgId: OrgId, issue: Issue): Promise<boolean> {
  const commentIds = await commentRepo.listCommentIdsForIssue(orgId, issue.id);
  for (const commentId of commentIds) {
    await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
  }
  await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);

  const purged = await issueRepo.purgeIssue(orgId, issue.id);
  if (purged === null) return false;

  const releasedMb = purged.attachmentSizes.reduce(
    (total, sizeBytes) => total + Math.ceil(sizeBytes / BYTES_PER_MB),
    0,
  );
  if (releasedMb > 0) {
    // A counter never goes below what is actually stored: clamp at zero.
    const usage = await usageRepo.getUsage(orgId);
    await usageRepo.incrementUsage(orgId, {
      storageMbUsed: -Math.min(releasedMb, usage.storageMbUsed),
    });
  }

  return true;
