/**
 * The retention sweep: expired issues are deleted for good, with everything
 * that hangs off them, and their numbers are never handed out again.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { getPlanLimits } from "@/config/plan-limits";
import {
  attachments,
  comments,
  getDb,
  issueLabels,
  issues,
  searchIndex,
} from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { addAttachment } from "@/server/services/attachment-service";
import { createComment } from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import { registerSearchListeners } from "@/server/services/search-service";
import { toIsoTimestamp } from "@/types/common";
import { eq } from "drizzle-orm";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

const DAY_MS = 24 * 60 * 60 * 1000;
const MB = 1024 * 1024;
const NOW = new Date("2026-06-01T07:00:00.000Z");

let cleanup: () => void;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerSearchListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

/** Archives an issue and back-dates `archived_at` to `ageMs` before NOW. */
async function archiveAt(tenant: Tenant, issueId: IssueId, ageMs: number): Promise<void> {
  await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issueId);
  getDb()
    .update(issues)
    .set({ archivedAt: toIsoTimestamp(new Date(NOW.getTime() - ageMs)) })
    .where(eq(issues.id, issueId))
    .run();
}

function count(table: typeof comments | typeof attachments | typeof issueLabels | typeof searchIndex, issueId: IssueId): number {
  const db = getDb();
  if (table === searchIndex) {
    return db.select().from(searchIndex).where(eq(searchIndex.subjectId, issueId)).all().length;
  }
  return db.select().from(table).where(eq(table.issueId, issueId)).all().length;
}

describe("the retention sweep", () => {
  it("deletes an expired issue with its comments, attachments and search documents", async () => {
    const tenant = await createTenant("sweep-full", "starter");
    const { retentionDays } = getPlanLimits("starter");
    await usageRepo.recomputeUsage(tenant.org.id);

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Purge me" }),
    );
    getDb()
      .insert(issueLabels)
      .values({ orgId: tenant.org.id, issueId: issue.id, labelId: "label-1" })
      .run();
    const comment = await createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "A comment on the doomed issue",
      parentId: null,
      mentionedUserIds: [],
    });
    await addAttachment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      filename: "a.png",
      contentType: "image/png",
      sizeBytes: Math.floor(1.5 * MB),
    });
    await addAttachment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      filename: "b.png",
      contentType: "image/png",
      sizeBytes: 3 * MB,
    });

    const keeper = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Keep me" }),
    );
    await addAttachment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: keeper.id,
      filename: "k.png",
      contentType: "image/png",
      sizeBytes: 2 * MB,
    });

    await archiveAt(tenant, issue.id, retentionDays * DAY_MS);
    const before = await usageRepo.getUsage(tenant.org.id);
    expect(before.storageMbUsed).toBe(2 + 3 + 2);

    const result = await runCleanupArchivedJob(NOW);

    expect(result.failed).toBe(0);
    expect(await issueRepo.findIssueById(tenant.org.id, issue.id)).toBeNull();
    expect(count(comments, issue.id)).toBe(0);
    expect(count(attachments, issue.id)).toBe(0);
    expect(count(issueLabels, issue.id)).toBe(0);
    expect(
      getDb().select().from(searchIndex).where(eq(searchIndex.subjectId, comment.id)).all(),
    ).toHaveLength(0);
    expect(count(searchIndex, issue.id)).toBe(0);

    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.storageMbUsed).toBe(2);
    expect(after.issuesUsed).toBe(before.issuesUsed);
    const recount = await usageRepo.recomputeUsage(tenant.org.id);
    expect(after.storageMbUsed).toBe(recount.storageMbUsed);

